const NOTE="Список считает собственный счётчик сайта за 7 дней: без cookie и без слежки, роботов не считает.";function esc(n){return String(n).replace(/[&<>"']/g,t=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[t])}function plural(n){const t=n%10,o=n%100;return t===1&&o!==11?"просмотр":t>=2&&t<=4&&(o<10||o>=20)?"просмотра":"просмотров"}async function boot(){const n=document.getElementById("popularList"),t=document.getElementById("popularNote");if(n)try{const o=await fetch("/popular.json",{cache:"no-store"});if(!o.ok)return;const r=await o.json(),a=(Array.isArray(r.top)?r.top:[]).filter(e=>e&&e.page&&Number(e.hits)>0).slice(0,10);if(!a.length)return;n.innerHTML=a.map(e=>{const i=Number(e.hits)||0;return'<li><a href="'+esc(e.page)+'">'+esc(e.title||e.page)+"</a>"+(i?' <span style="color:var(--text-muted);font-size:13px">— '+i+" "+plural(i)+"</span>":"")+"</li>"}).join(""),t&&(t.textContent="Данные за 7 дней, обновлено "+(r.built_at||"")+". "+NOTE)}catch{}}typeof document<"u"&&(document.readyState==="loading"?document.addEventListener("DOMContentLoaded",boot):boot());
